import { Flex, SegmentedControl, Tabs, useTheme, useThemeValue } from '@gravity-ui/uikit';
import React, { useState } from 'react';
import type { RealTheme } from '@gravity-ui/uikit';
import { Overview } from './pages/Overview';
import { Projects } from './pages/Projects';
import { Settings } from './pages/Settings';
import type { PageId } from './types';
import './styles/app.css';

const navigationItems = [
  { id: 'overview', title: 'Обзор' },
  { id: 'projects', title: 'Проекты' },
  { id: 'settings', title: 'Настройки' },
];

export function App() {
  const [page, setPage] = useState<PageId>('overview');
  const [theme, setTheme] = useState<RealTheme>('light');
  const selectedTheme = useThemeValue();
  const currentTheme = theme ?? selectedTheme;

  return (
    <Flex direction="column" className="app" gap="6">
      <header className="app__header">
        <Flex className="app__content" direction="column" padding="5" gap="4">
          <Flex alignItems="center" justifyContent="space-between" gap="4">
            <Text variant="header-2" as="span">
              Рабочая панель
            </Text>
            <SegmentedControl
              size="m"
              value={theme === 'light-hc' ? 'light' : theme === 'dark-hc' ? 'dark' : theme}
              onUpdate={(value) =>
                setTheme(value === 'dark' ? (theme.endsWith('hc') ? `${theme.replace('-hc', '')}-hc` : 'dark') as RealTheme : theme.endsWith('hc') ? theme.replace('dark', 'light') as RealTheme : 'light')
              }
              options={[
                { value: 'light', content: 'Светлая' },
                { value: 'dark', content: 'Тёмная' },
              ]}
            />
          </Flex>
          <Tabs
            items={navigationItems}
            activeTab={page}
            onSelectTab={(nextPage) => setPage(nextPage as PageId)}
            size="m"
          />
        </Flex>
      </header>

      <main className="app__content" style={{ padding: 'var(--g-spacing-xl)' }}>
        {page === 'overview' && <Overview />}
        {page === 'projects' && <Projects />}
        {page === 'settings' && <Settings theme={currentTheme} onThemeChange={setTheme} />}
      </main>
    </Flex>
  );
}

