import { Card, Flex, Select, Switch, Text } from '@gravity-ui/uikit';
import type { RealTheme } from '@gravity-ui/uikit';

interface SettingsProps {
  theme: RealTheme;
  onThemeChange: (theme: RealTheme) => void;
}

export function Settings({ theme, onThemeChange }: SettingsProps) {
  return (
    <section className="page" aria-labelledby="settings-title">
      <Text variant="header-1" as="h1" id="settings-title">
        Настройки
      </Text>
      <Text color="secondary">Оформление и базовые параметры приложения.</Text>

      <Card type="container" view="filled" padding="6">
        <Flex direction="column" gap="6">
          <Flex direction="column" gap="3">
            <Text variant="header-2" as="h2">
              Тема
            </Text>
            <Flex alignItems="center" justifyContent="space-between">
              <Flex direction="column">
                <Text>Тёмная тема</Text>
                <Text color="secondary">Использовать тёмное оформление.</Text>
              </Flex>
              <Switch
                checked={theme === 'dark'}
                onChange={(event) => onThemeChange(event.target.checked ? 'dark' : 'light')}
              />
            </Flex>
            <Select
              value={[theme]}
              onUpdate={(values) => {
                const value = values.at(-1);
                if (value === 'light' || value === 'light-hc' || value === 'dark' || value === 'dark-hc') {
                  onThemeChange(value);
                }
              }}
              options={[
