              <Flex direction="column">
                <Text>Тёмная тема</Text>
                <Text color="secondary">Использовать тёмное оформление.</Text>
              </Flex>
              <Switch
                checked={theme === 'dark'}
                onChange={(event) => onThemeChange(event.target.checked ? 'dark' : 'light')}
              />
            </Flex>
            <Select
              value={[theme]}
              onUpdate={(values) => {
                const value = values.at(-1);
                if (value === 'light' || value === 'light-hc' || value === 'dark' || value === 'dark-hc') {
                  onThemeChange(value);
                }
              }}
              options={[
